1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.function.owner.Locality;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.time.LocalDate;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /** Format an owner's name for display as 'LastName, FirstName'. */
31	    default String displayName(Owner owner) {
32	        return owner.getLastName() + ", " + owner.getFirstName();
33	    }
34	
35	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
36	    default String initials(Owner owner) {
37	        return initial(owner.getFirstName()) + initial(owner.getLastName());
38	    }
39	
40	    private String initial(String name) {
41	        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
42	    }
43	
44	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
45	     *  last two digits of the registration date's year (e.g. 'SPR-SMI-0007-M26'). Absent until both the
46	     *  customer code and registration date have been assigned. */
47	    default String membershipNumber(Owner owner) {
48	        String customerCode = owner.getCustomerCode();
49	        LocalDate registrationDate = owner.getRegistrationDate();
50	        if (customerCode == null || registrationDate == null) {
51	            return null;
52	        }
53	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
54	    }
55	
56	    /** The owner's membership tier: 'SILVER' when the owner has no namesakes (namesakeCount is 0)
57	     *  and an email on file, otherwise 'BRONZE'. */
58	    default String membershipTier(Owner owner) {
59	        Integer namesakeCount = owner.getNamesakeCount();
60	        String email = owner.getEmail();
61	        boolean silver = namesakeCount != null && namesakeCount == 0 && email != null && !email.isBlank();
62	        return silver ? "SILVER" : "BRONZE";
63	    }
64	
65	    /** The owner's region, derived from its city via the fixed city-to-region table
66	     *  (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), or 'UNKNOWN' otherwise. */
67	    default String locality(Owner owner) {
68	        return Locality.region(owner.getCity());
69	    }
70	
71	    Owner toOwner(OwnerDto ownerDto);
72	
73	    @Mapping(target = "id", ignore = true)
74	    @Mapping(target = "pets", ignore = true)
75	    Owner toOwner(OwnerFieldsDto ownerDto);
76	
77	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
78	
79	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
80	
81	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
82	        OwnerPageDto ownerPageDto = new OwnerPageDto();
83	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
84	        ownerPageDto.setPage(ownerPage.getNumber());
85	        ownerPageDto.setSize(ownerPage.getSize());
86	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
87	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
88	        return ownerPageDto;
89	    }
90	}
