     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.util.Locale;
     4	import java.util.regex.Pattern;
     5	
     6	import net.officefloor.plugin.variable.Val;
     7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
     9	
    10	/**
    11	 * Create-owner step: email is optional, so a missing or blank value is left untouched.
    12	 * When present it must be a syntactically valid address, otherwise the request is rejected
    13	 * with a 400; a valid address is stored lower-cased so it is persisted and returned in
    14	 * canonical form. Runs after {@link NormalizeOwnerTelephone} and before {@link BuildOwner},
    15	 * mutating the published body in place. Mirrors {@link NormalizeOwnerTelephone}.
    16	 */
    17	public class NormalizeOwnerEmail {
    18	
    19	    /** A local part, an '@', then a dotted domain with a non-numeric top-level label. */
    20	    private static final Pattern EMAIL =
    21	        Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)*\\.[^@\\s.\\d]+$");
    22	
    23	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
    24	        String email = request.getEmail();
    25	        if (email == null || email.isBlank()) {
    26	            return;
    27	        }
    28	        String normalized = email.trim().toLowerCase(Locale.ROOT);
    29	        if (!EMAIL.matcher(normalized).matches()) {
    30	            throw new InvalidEmailException();
    31	        }
    32	        request.setEmail(normalized);
    33	    }
    34	}
