     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Val;
     4	import org.springframework.samples.petclinic.model.Owner;
     5	import org.springframework.samples.petclinic.repository.OwnerRepository;
     6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
     8	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
     9	
    10	/**
    11	 * Create-owner step: rejects the request with a 409 when its telephone is already used by
    12	 * any existing owner, comparing telephones in canonical E.164 form (see
    13	 * {@link E164Telephone}). Runs after {@link NormalizeOwnerTelephone} (so the request
    14	 * already holds the E.164 value) and before {@link BuildOwner}.
    15	 */
    16	public class EnsureUniqueTelephone {
    17	
    18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
    19	            throws DuplicateTelephoneException {
    20	        String telephone = request.getTelephone();
    21	        for (Owner owner : ownerRepository.findAll()) {
    22	            if (telephone.equals(canonical(owner.getTelephone()))) {
    23	                throw new DuplicateTelephoneException(telephone);
    24	            }
    25	        }
    26	    }
    27	
    28	    /** An existing telephone in E.164 form, or {@code null} when it cannot be normalized
    29	     *  (such a stored value never matches a valid incoming number). */
    30	    private static String canonical(String stored) {
    31	        try {
    32	            return E164Telephone.normalize(stored);
    33	        }
    34	        catch (InvalidTelephoneException ex) {
    35	            return null;
    36	        }
    37	    }
    38	}
