     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Val;
     4	import org.springframework.samples.petclinic.model.Owner;
     5	import org.springframework.samples.petclinic.repository.OwnerRepository;
     6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
     8	
     9	/**
    10	 * Create-owner step: rejects the request with a 409 when another owner already shares the
    11	 * same {@link Household} — the same last name and address. Skipped when the request opts
    12	 * in with {@code sharesHousehold: true}, in which case {@link AssignHousehold} instead
    13	 * links the owners under a shared identifier. Runs after {@link ValidateOwnerFields} (so
    14	 * the required fields are present) and before {@link BuildOwner}.
    15	 */
    16	public class EnsureUniqueHousehold {
    17	
    18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
    19	            throws DuplicateHouseholdException {
    20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
    21	            return;
    22	        }
    23	        for (Owner owner : ownerRepository.findAll()) {
    24	            if (Household.matches(owner, request.getLastName(), request.getAddress())) {
    25	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
    26	            }
    27	        }
    28	    }
    29	}
