     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Val;
     4	import org.springframework.samples.petclinic.repository.OwnerRepository;
     5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     6	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
     7	
     8	/**
     9	 * Create-owner step: rejects the request with a 409 when the new owner's city already holds
    10	 * {@link #CAPACITY} or more owners (compared case-insensitively, see {@link SameCity}). Runs
    11	 * after {@link ValidateOwnerFields} (so the city is present) and before {@link BuildOwner}.
    12	 */
    13	public class EnsureCityHasCapacity {
    14	
    15	    /** The maximum number of owners a single city may hold. */
    16	    static final int CAPACITY = 50;
    17	
    18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
    19	            throws CityAtCapacityException {
    20	        if (SameCity.count(ownerRepository.findAll(), request.getCity()) >= CAPACITY) {
    21	            throw new CityAtCapacityException(request.getCity(), CAPACITY);
    22	        }
    23	    }
    24	}
########## /home/daniel/sandbox/src/main/java/org/springframework/samples/petclinic/rest/function/owner/EnsureDailyOwnerLimit.java ##########
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import org.springframework.samples.petclinic.model.Owner;
     4	import org.springframework.samples.petclinic.repository.OwnerRepository;
     5	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
     6	
     7	/**
     8	 * Create-owner step: rejects the request with a 429 when {@link #DAILY_LIMIT} or more owners
     9	 * have already been registered on today's business day (by {@link Owner#getRegistrationDate()}).
    10	 * The server date is rolled forward over weekends (see {@link BusinessDay}) so it matches the
    11	 * adjusted registration dates the new and existing owners carry. Reads only the existing owners,
    12	 * so it can run before the new owner is built.
    13	 */
