     8	/**
     9	 * Create-owner step for the {@code sharesHousehold} opt-in: when the request joins an
    10	 * existing {@link Household} (another owner with the same last name and address), assigns
    11	 * the shared household identifier to both the new owner and every existing member, so all
    12	 * owners in the household report the same {@code householdId}. A no-op when the request
    13	 * does not opt in or joins no existing owner. Runs after {@link BuildOwner} and before
    14	 * {@link SaveOwner} persists the new owner.
    15	 */
    16	public class AssignHousehold {
    17	
    18	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
    19	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
    20	            return;
    21	        }
    22	        String householdId = Household.id(owner.getLastName(), owner.getAddress());
    23	        boolean joined = false;
    24	        for (Owner member : ownerRepository.findAll()) {
    25	            if (Household.matches(member, owner.getLastName(), owner.getAddress())) {
    26	                member.setHouseholdId(householdId);
    27	                ownerRepository.save(member);
    28	                joined = true;
    29	            }
    30	        }
    31	        if (joined) {
    32	            owner.setHouseholdId(householdId);
    33	        }
    34	    }
